import{z as B,x as A,o as n,c as p,q as s,j as i,D as t,d as e,s as o,S as l,b as r}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"工作集","description":"","frontmatter":{"title":"工作集","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/working-set.md","filePath":"cs/working-set.md","lastUpdated":1791063341000}'),d={name:"cs/working-set.md"};function C(m,a,c,h,D,f){const E=A("Mermaid");return n(),p("div",null,[a[2]||(a[2]=s('<h1 id="工作集" tabindex="-1">工作集 <a class="header-anchor" href="#工作集" aria-label="Permalink to &quot;工作集&quot;">​</a></h1><div class="epigraph"><p>程序在时刻 t 的工作集，是过去 Δ 个引用里触及的页集合；驻留集应盖住它，而不是盖住整个虚空间。</p><footer>—— 据 Denning, The Working Set Model for Program Behavior, CACM 1968 整理</footer></div><p><a href="/cs/clock-replace">上一课</a>能在帧之间转圈，却没有说<strong>该给这个进程多少帧</strong>。<a href="/cs/demand-paging">按需调页</a>已用工作集解释「虚大于物仍可跑」，当时是口号。缺口是把 Δ 窗口收成置换与多道的输入：工作集大小 W(t, Δ) 随相位变；时钟指针应优先留下窗口内的页。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>全局 CLOCK 可能把刚要跑的进程页全部抢走，下一次调度立刻 major 缺页。局部配额若是固定帧数，相位一变就浪费或不足。Denning 的缺口：用近期引用集当「现在必须在内存里的页」。Δ 太大则工作集接近全部虚页；太小则抖动。本课不把 Δ 的最优估计写成一条公式交差。</p><p><span class="marginnote">数字实例：Δ=10 次引用内依次碰了页 3、7、3、9、3、7、12、3、9、7，工作集是 {3, 7, 9, 12} 共 4 页——重复命中的页不重复计数，集合大小是 4 而不是 10。</span></p><p>本课不引入工作集采样的全部内核计数器。</p><p><span class="marginnote">WSClock：时钟扫描时看「上次使用是否落在 Δ 内」，把 CLOCK 与工作集合并。PFF（缺页频率）用缺页率涨落加减帧，是另一条控制回路。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>为进程维护近期页集合（硬件访问位 + 周期性采样，或引用串的软件窗口）。置换时：窗口内的页不当牺牲；窗口外的可以给 CLOCK 扔掉。分配帧时：试图让驻留集 ≥ W(t, Δ)。做不到就不要再提高多道——下一课抖动。预调可以一次装入工作集的邻页，仍属按需的加速，不是改变窗口定义。</p><p><span class="marginnote">常见误区：把「驻留集对准工作集」当成内核精确算出来的数。真实实现只有采样与近似：访问位只能告诉你「Δ 内碰没碰过」，谈不上逐引用回放；PFF 更是用缺页率这个可观测量直接代替 W 来加减帧。</span></p>',11)),(n(),i(l,null,{default:t(()=>[o(E,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20REF%5B%22%E5%BC%95%E7%94%A8%E4%B8%B2%22%5D%20--%3E%20WIN%5B%22%E7%AA%97%E5%8F%A3%20%CE%94%22%5D%0A%20%20WIN%20--%3E%20WS%5B%22%E5%B7%A5%E4%BD%9C%E9%9B%86%20W%22%5D%0A%20%20WS%20--%3E%20RES%5B%22%E9%A9%BB%E7%95%99%E9%9B%86%E5%BA%94%E8%A6%86%E7%9B%96%20W%22%5D%0A%20%20RES%20--%3E%20CLK%5B%22CLOCK%20%E5%8F%AA%E6%B7%98%E6%B1%B0%E7%AA%97%E5%A4%96%E9%A1%B5%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[e("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,[e("工作集把局部性从 Cache 课接到多道：CPU 调度看到的「可运行」，隐含「其工作集已在内存」。否则调度只是把缺页从一个进程转到另一个。它不改 "),r("a",{href:"/cs/paging-vm"},"分页"),e(" 的翻译，只改帧的归属策略。与公平调度对照：CFS 分的是 CPU 时间；工作集分的是帧。两者同时紧张时，先减多道比先减时间片更对——理由下一课展开。")],-1)),a[5]||(a[5]=r("p",null,"工作集之和超出物理内存时，控制环往哪个方向走：",-1)),(n(),i(l,null,{default:t(()=>[o(E,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22%E9%87%87%E6%A0%B7%E5%90%84%E8%BF%9B%E7%A8%8B%E5%B7%A5%E4%BD%9C%E9%9B%86%20W%22%5D%20--%3E%20Q%7B%22%E5%90%84%20W%20%E4%B9%8B%E5%92%8C%E8%83%BD%E8%A3%85%E4%B8%8B%E5%90%97%22%7D%0A%20%20Q%20--%3E%7C%22%E8%83%BD%22%7C%20OK%5B%22%E5%85%A8%E9%83%A8%E9%A9%BB%E7%95%99%EF%BC%8C%E6%AD%A3%E5%B8%B8%E8%BF%90%E8%A1%8C%22%5D%0A%20%20Q%20--%3E%7C%22%E4%B8%8D%E8%83%BD%22%7C%20DEC%5B%22%E5%87%8F%E5%A4%9A%E9%81%93%EF%BC%9A%E6%8C%82%E8%B5%B7%E4%B8%80%E4%B8%AA%E8%BF%9B%E7%A8%8B%22%5D%0A%20%20DEC%20--%3E%20SW%5B%22%E6%8A%8A%E5%AE%83%E7%9A%84%E5%B7%A5%E4%BD%9C%E9%9B%86%E6%95%B4%E4%BD%93%E6%8D%A2%E5%87%BA%22%5D%0A%20%20SW%20--%3E%20M%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=s('<p><span class="marginnote">为什么重要：调度器挑进程时若不看它的工作集是否驻留，被选中的进程会立刻连环缺页——CPU 时间没省下，磁盘队列反而更长。Denning 把「工作集在内存」设为可调度的前提，就是这个原因。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不保证能精确测量 W：采样有滞后，多线程共享地址空间时窗口是进程级还是线程级，实现各异。也不把工作集当成数据库缓冲池的同义词；那是文件页 Cache 的后课。Δ 与时钟中断频率有关，但不是 jiffies 课。</p><p>后课默认：驻留集应对准工作集。当所有进程的 W 之和超过物理内存，任何置换都会失败，下一课叫抖动。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>工作集是窗口 Δ 内的页集；驻留应覆盖它。</li><li>WSClock / PFF 是把窗口接到 CLOCK 的控制。</li><li>覆盖失败时的系统行为是抖动课的缺口。</li><li>出处：Denning, <em>CACM</em> 1968；Silberschatz et al., <em>OSC</em>；Tanenbaum <em>MOS</em>。</li></ul>',6))])}const S=B(d,[["render",C]]);export{u as __pageData,S as default};
